TArrayView<const FNpcTranslationBody> NpcTranslationBodies()
{
	return MakeArrayView(GBodies);
}

TArrayView<const FNpcClass> NpcClasses()
{
	return MakeArrayView(GClasses);
}

TArrayView<const FNpcEntityAlias> NpcEntityAliases()
{
	return MakeArrayView(GAliases);
}

TArrayView<const FNpcTaskHandler> NpcTaskHandlers()
{
	return MakeArrayView(GTaskHandlers);
}

TArrayView<const FNpcTaskPolicy> NpcTaskPolicies()
{
	return MakeArrayView(GTaskPolicies);
}

TArrayView<const FNpcGrappleFamily> NpcGrappleFamilies()
{
	return MakeArrayView(GGrappleFamilies);
}

TArrayView<const TCHAR* const> NpcGrappleRoleSuffixes(ENpcGrappleRoleOrder Order)
{
	switch (Order)
	{
	case ENpcGrappleRoleOrder::AttackerVictimSwapped:
		return MakeArrayView(GGrappleRolesAttackerVictimSwapped);
	case ENpcGrappleRoleOrder::Canonical:
		break;
	}
	return MakeArrayView(GGrappleRolesCanonical);
}

